steps.script:
var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
var u = GameState.get_unit("U_WOLF_GUARD_TERMINATORS_B")
var w4 := 0
var w3 := 0
for c in layer.get_children():
	if c.has_meta("unit_id") and str(c.get_meta("unit_id")) == "U_WOLF_GUARD_TERMINATORS_B":
		for m in u.models:
			if str(m.id) == str(c.get_meta("model_id")):
				if int(m.wounds) == 4:
					w4 += 1
				elif int(m.wounds) == 3:
					w3 += 1
print("[sw11e-s4] terminator tokens: health bars of 4 W = ", w4, ", 3 W = ", w3)
return "%d,%d" % [w4, w3]

var groups: Array = Allocation.build_groups(GameState.get_unit("U_WOLF_GUARD_TERMINATORS_B"))
var out := []
for g in groups:
	out.append("%d:%d" % [int(g.w), g.model_indices.size()])
out.sort()
print("[sw11e-s4] terminator allocation groups ", out)
return ",".join(PackedStringArray(out))

var u = GameState.get_unit("U_THUNDERWOLF_CAVALRY_B")
var n := 0
for m in u.models:
	if RulesEngine._get_model_effective_invuln(m, u, int(m.get("invuln", 0))) == 4:
		n += 1
return n

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sw11e-s4] debug-log ERROR: ", l)
return n
